INSERT IGNORE INTO `page_text` (`ID`,`Text`,`NextPageID`,`PlayerConditionID`,`Flags`,`VerifiedBuild`) VALUES
(10323,'Как только бой утих, они принялись поднимать огромные ящики с камнями ветров на вершину башни. Их предводитель, какой-то жрец, упоминал о некоем ритуале.\r\n\r\nЯ пишу эту записку на случай, если не успею вернуться в Шен\'дар и предупредить Аонду. Они здесь явно затевают что-то недоброе.',10324,0,0,70338),
(10324,'Если вы нашли мое послание, пожалуйста, сделайте все возможное, чтобы остановить их. К настоящему моменту, когда я готовлюсь ползти прочь, у башни остается всего несколько супостатов.\r\n\r\nПостарайтесь забрать счастливое перо Раани с его тела. Он любил рассказывать небылицы о том, как вырвал его у какого-то огнекрыла, и мне кажется, ему бы хотелось, чтобы перо вернули к нему домой.\r\n\r\nА если у вас будет возможность забрать с тела Арвенсия Песня Теней его фамильный перстень, то прошу вас сделать и это. Верховный старейшина Песня Теней – его дядя, и он хотел бы, чтобы перстень возвратили обратно семье.',0,0,0,70338),
(10723,'"Основание нашего нового заоблачного дома знаменует для нашего народа начало новой эры мира и процветания.\r\n\r\nВы все выдержали множество испытаний, чтобы оказаться здесь. На моих глазах вы превратились в выносливый и независимый народ, и я не могу передать словами, какая гордость переполняет меня.\r\n\r\nОднако наибольшую радость приносит осознание, что мне больше не требуется служить нашим единственным правителем".',10724,0,0,70338),
(10724,'"Thus, I am abdicating my position as your leader and handing over governance of our Skyborne Isles to a carefully chosen council of provincial elders. After the transition period is over, you will have the opportunity to choose your own leaders, and your voices will determine the direction we take from here on. \r\n\r\nYou have demonstrated the ability to lead yourselves better than any king, queen, prince, or other individual sovereign ever could--and that fills me with profound pride."',10725,0,0,70338),
(10725,'"I will continue to serve our people here on Zephras, and I will devote much of my time to furthering our relationship with the wind spirits to whom we owe so much. The elemental spirits are wondrous and wise, and we still have so much to learn from one another.\r\n\r\nI am devoted to seeing the shen\'dorei persevere in this beautiful and strange realm--and to seeing that we do so freely, justly, and unshackled by tyranny."',10726,0,0,70338),
(10726,'"От всего сердца благодарю вас за все, чем вы пожертвовали, все, что вы создали, и все, чему научили меня, помогая стать лучше. Вы воплощение несгибаемой воли народа шен\'дорай. Вместе мы найдем свое счастье в этом прекрасном новом мире и достигнем новых высот".',0,0,0,70338),
(10733,'"В дни, последовавшие за происшествием у Источника Вечности, в Эльдре\'Таласе воцарился ужасный хаос. Демоны, хлынувшие из Источника, едва не сокрушили эльфийские королевства – чудовища разоряли землю и убивали без разбора. Если бы не вмешательство полубога Голдринна и жертвы бесчисленных героев калдорай, королевство Эльдре\'Талас было бы захвачено и уничтожено".',10734,0,0,70338),
(10734,'"Вскоре после переломных событий войны и Великого Раскола Калимдора мы столкнулись с новой суровой реальностью: в мире больше не существовало могучих источников магии, на которые мы полагались. Тортелдрин, правящий род Эльдре\'Таласа, поспешил предпринять действия, которые должны были обеспечить нашему народу стабильность и возвращение к привычному образу жизни. Но действия эти вызвали у многих глубокое беспокойство".',10735,0,0,70338),
(10735,'"Молодой принц Тортелдрин собирался возвести сеть кристальных средоточий и таким образом добыть и сформировать для нас новый источник силы. Камнем преткновения для многих стал тот факт, что для этого принц решил прибегнуть к силе, которая чуть не уничтожила наш мир. Он намеревался призвать ее из мира демонов в Круговерти Пустоты. \r\n\r\nМногие справедливо опасались, что этим самым он откроет для демонов новую лазейку, через которую те смогут проникнуть в наш мир".',0,0,0,70338),
(10908,'"Большая часть флоры и фауны Небесных островов сформировалась под воздействием стихий, царящих в Небесной выси. Многие наземные существа обрели здесь такие птичьи черты, как клювы, когтистые лапы и перья. Некоторые и вовсе развили способность летать, однако такая трансформация встречается реже, нежели другие внешние изменения.\r\n\r\nНа народ шен\'дорай царство стихий влияло медленно и постепенно, однако его эффекты оказались гораздо более заметными у нового поколения. Взять, к примеру, явление, теперь широко называемое небесным благословением".',10909,0,0,70338),
(10909,'"Хорошо известно, что после восхождения в Небесную высь наши тела стали более гибкими и стройными, но это происходило на протяжении многих тысячелетий. Однако первый известный случай небесного благословения – из-за которого дети шен\'дорай рождаются с ярко-лазурной кожей – был отмечен менее пяти поколений назад.\r\n\r\nВ рамках одного поколения после первого появления этой странной черты она проявлялась у одного из двадцати детей, появившихся на свет у небеснорожденных. Через два поколения этот показатель удвоился".',10910,0,0,70338),
(10910,'"Сегодня же небесное благословение касается трех из десяти детей, рождающихся на Небесных островах. В последние несколько столетий темпы наших физических изменений значительно ускорились, и многие ученые считают, что мы можем полностью утратить черты предков калдорай через два-три поколения.\r\n\r\nВозможно, мы никогда полностью не постигнем причину этой трансформации. Однако совершенно очевидно, что наш дом в измерении стихий изменяет и преображает весь наш народ. Небесная высь – царство загадок и чудес, но это наблюдение служит отрезвляющим напоминанием: мы до сих пор опасно мало знаем, как такое место может влиять на тех, кто в нем не родился".',0,0,0,70338),
(10961,'Приветствую, $n!\r\n\r\nС тех пор как исчезли духи ветра, Зефрис находится на грани гибели. Птицы, звери и даже корни под нашими ногами взывают о помощи.\r\n\r\nРазыщи меня на нижнем уровне великого древа в деревне Тендал. Я помогу тебе советом и обучу тебя искусству друидов.\r\n\r\nЗитон Среброветрый, наставник друидов',0,0,0,70338);
